//! **IDE-wide Claude Code settings** (spec 084): the access token the IDE's
//! tool server admits, kept beside `debug_settings.toml` in the IDE's data
//! folder — never in a project. The port stays `LlmConfig::mcp_port`.
//!
//! The token is generated by Configure Claude Code (and Renew token), handed to
//! Claude Code's plugin configuration, and never written to a log, the Output
//! pane, a project file or a tool answer (R38).

use std::path::PathBuf;

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default)]
pub struct ClaudeCodeSettings {
    /// The access token; empty until Configure Claude Code generates one.
    pub token: String,
}

impl ClaudeCodeSettings {
    pub fn path() -> PathBuf {
        crate::llm::base_dir().join("claude_code.toml")
    }

    /// The saved settings, or defaults when there are none or they are unreadable.
    pub fn load() -> Self {
        std::fs::read_to_string(Self::path())
            .ok()
            .and_then(|t| toml::from_str(&t).ok())
            .unwrap_or_default()
    }

    pub fn save(&self) -> Result<(), String> {
        let path = Self::path();
        if let Some(dir) = path.parent() {
            std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
        }
        let text = toml::to_string_pretty(self).map_err(|e| e.to_string())?;
        std::fs::write(&path, text).map_err(|e| e.to_string())?;
        // The token is a credential: readable by this user only.
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let _ = std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o600));
        }
        Ok(())
    }

    /// The token, when one has been generated.
    pub fn token(&self) -> Option<String> {
        Some(self.token.clone()).filter(|t| !t.trim().is_empty())
    }

    /// Replace the token with a fresh one (Configure the first time, Renew
    /// token after) and return it.
    pub fn renew_token(&mut self) -> String {
        self.token = new_token();
        self.token.clone()
    }
}

/// 32 bytes from the operating system's generator, as 64 hex digits.
pub fn new_token() -> String {
    use rand::RngCore;
    let mut bytes = [0u8; 32];
    rand::rngs::OsRng.fill_bytes(&mut bytes);
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tokens_are_long_unique_and_hex() {
        let a = new_token();
        let b = new_token();
        assert_eq!(a.len(), 64);
        assert!(a.chars().all(|c| c.is_ascii_hexdigit()));
        assert_ne!(a, b, "two tokens differ");
        let mut s = ClaudeCodeSettings::default();
        assert_eq!(s.token(), None, "no token until one is generated");
        let t = s.renew_token();
        assert_eq!(s.token(), Some(t));
        println!("tokens: 64 hex digits from the OS generator, two draws differ, none before Configure");
    }
}
